import{_ as a,o as t,a as i,a2 as n}from"./chunks/framework.B1yo9hPv.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"text":"FAIR Science for Earth Action","tagline":"Create, find, and collaborate on Earth system science experiments, unlocking the full potential of Earth Observation for the benefit of society - from research to policy","background":"https://earthcode.esa.int/img/earthcode-infographic-pillars-Nologo.jpg","image":"https://earthcode.esa.int/img/earthcode-infographic-pillars.jpg","actions":[{"theme":"cta","text":"Explore Dashboard","link":"/explore"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),o={name:"index.md"};function r(s,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<section class="light-grey"><h2 id="interactive-datacube-visualizations" tabindex="-1">Interactive Datacube Visualizations <a class="header-anchor" href="#interactive-datacube-visualizations" aria-label="Permalink to &quot;Interactive Datacube Visualizations&quot;">​</a></h2><p>The Dashboard now hosts interactive web visualizations for the two GeoZarr datacubes, developed as part of the ESA EarthCODE hackathons. These datacubes provide standardized spatial and temporal grids, enabling multi-variable exploration directly in the browser with interactive variable selection, depth slicing, dynamic range adjustments, and time navigation.</p><h3 id="esa-mediterranean-sea-datacubes" tabindex="-1">ESA Mediterranean Sea Datacubes <a class="header-anchor" href="#esa-mediterranean-sea-datacubes" aria-label="Permalink to &quot;ESA Mediterranean Sea Datacubes&quot;">​</a></h3><p>The <a href="https://esa-earthcode.github.io/ocean_hackathon/datacube/intro/" target="_blank" rel="noreferrer">ESA Mediterranean Sea Datacube</a> brings selected marine datasets onto a unified 1/24° latitude/longitude grid (EPSG:4326) across the Mediterranean basin. By aligning physical and biogeochemical observations, variables can be inspected and compared without manual spatial realignment.</p><p>Hosted collections:</p><ul><li><strong>Daily Surface Fields:</strong> Sea surface salinity, density, sea level anomalies, absolute dynamic topography, and finite-size Lyapunov exponents.</li><li><strong>Monthly Fields:</strong> Total and size-fractionated phytoplankton carbon, marine heatwaves, cold spells, and composite hazard indicators.</li><li><strong>3D Biophysics:</strong> Daily temperature, salinity, primary production, euphotic depth, mixed layer depth, and geostrophic velocities across 18 depth levels.</li><li><strong>Hourly Currents:</strong> Zonal and meridional surface currents, ageostrophic components, and total current velocities.</li></ul><h3 id="esa-antarctica-datacubes" tabindex="-1">ESA Antarctica Datacubes <a class="header-anchor" href="#esa-antarctica-datacubes" aria-label="Permalink to &quot;ESA Antarctica Datacubes&quot;">​</a></h3><p>The <a href="https://esa-earthcode.github.io/polar_hackathon/intro/" target="_blank" rel="noreferrer">ESA Antarctica Datacube</a> integrates Antarctic scientific datasets into analysis-ready Zarr stores, standardizing them onto common polar coordinate systems to eliminate preprocessing overhead like reprojection, resampling, and spatial joins.</p><p>Hosted collections:</p><ul><li><strong>Land Ice (EPSG:3031):</strong><ul><li><strong>Internal Ice Temperature:</strong> 3D thermal structure modeled across 91 vertical depth levels below the ice sheet surface.</li><li><strong>Surface Elevation Change (SEC):</strong> Rate of elevation change, uncertainties, surface classifications, and IMBIE basin identifiers across 27 observation periods.</li><li><strong>Combined Bed &amp; Ice Sheet:</strong> Bedrock topography, ice thickness, surface elevation, firn air content, geoid height, and grounding line locations.</li><li><strong>Composite Ice Mask:</strong> Multi-temporal Antarctic ice-front composite masks spanning 1997–2021.</li><li><strong>Ice Velocity:</strong> Surface velocity magnitude, directional velocity components (easting, northing, vertical), and measurement counts over 87 time steps.</li></ul></li><li><strong>Sea Ice (EPSG:6932):</strong><ul><li>Sea-ice floe density, radar freeboard, sea-ice thickness, snow depth, and proximity to open ocean and leads across 146 observation dates.</li></ul></li></ul></section>',1)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
